def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    total_players = 1 + len(alive)
    units = int(supply // WATER_REQ)
    scarcity = total_players - units

    prev_bids = []
    desperate_opp = False
    rich_pressure = False
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 2:
            desperate_opp = True
        if opp.get('budget', 0) > budget * 1.2:
            rich_pressure = True

    if hp <= 2 or no_water >= 2:
        base = DAILY_SALARY * 0.95
    elif hp <= 4 or no_water == 1:
        base = DAILY_SALARY * 0.72
    else:
        if scarcity <= 0:
            base = DAILY_SALARY * 0.22
        elif scarcity == 1:
            base = DAILY_SALARY * 0.42
        elif scarcity == 2:
            base = DAILY_SALARY * 0.58
        else:
            base = DAILY_SALARY * 0.72

    if prev_bids:
        highest_prev = max(prev_bids)
        if highest_prev >= DAILY_SALARY * 0.9:
            if hp > 4 and no_water == 0:
                base = min(base, DAILY_SALARY * 0.28)
            else:
                base = max(base, DAILY_SALARY * 0.88)
        elif highest_prev >= DAILY_SALARY * 0.6:
            base = max(base, min(DAILY_SALARY * 0.78, highest_prev + 2))
        else:
            base = max(base, highest_prev + 1)

    if desperate_opp and hp > 4 and no_water == 0:
        base = min(base, DAILY_SALARY * 0.35)
    if rich_pressure and scarcity > 0 and (hp <= 4 or no_water >= 1):
        base = max(base, DAILY_SALARY * 0.8)

    days_left = max(1, 10 - day_context['day'] + 1)
    soft_cap = budget / days_left + DAILY_SALARY * 0.15
    if hp > 4 and no_water == 0:
        bid = min(base, soft_cap)
    else:
        bid = base

    bid = max(0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Identify alive opponents and extract yesterday bids
    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    yesterday_bids = []
    yesterday_highest = None
    yesterday_second = None

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                continue
            yesterday_bids.append(b_val)

    if yesterday_bids:
        yesterday_bids.sort(reverse=True)
        yesterday_highest = yesterday_bids[0]
        yesterday_second = yesterday_bids[1] if len(yesterday_bids) > 1 else None

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Convert supply to an estimate of how many full water units are likely available per requirement.
    # We use this only to scale our aggressiveness.
    supply_units = supply / float(WATER_REQ) if WATER_REQ > 0 else 1.0

    # Aggression thresholds based on typical behavior: near salary => high pressure.
    high_pressure = (yesterday_highest is not None and yesterday_highest >= 0.85 * DAILY_SALARY)
    medium_pressure = (yesterday_highest is not None and yesterday_highest >= 0.60 * DAILY_SALARY)

    # Base bid: aim to secure at least one requirement when possible.
    # If our budget is low, cap aggressively.
    target_min = 0.0
    # If supply is low, increase willingness to bid.
    if supply <= float(MIN_SUPPLY) + 1e-9:
        target_min = 0.55 * DAILY_SALARY
    elif supply >= float(MAX_SUPPLY) - 1e-9:
        target_min = 0.35 * DAILY_SALARY
    else:
        # Interpolate between low and high supply
        t = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        target_min = (0.55 - 0.20 * t) * DAILY_SALARY

    # HP/burn logic: if we are in danger, bid harder.
    danger = (hp <= 2.0) or (no_water_days >= 2)

    if not alive_opponents:
        # No one to compete: bid conservatively but enough to avoid starvation.
        bid = max(target_min * 0.5, 0.25 * DAILY_SALARY)
        return min(budget, bid)

    # If they bid very high yesterday, they likely anticipate scarcity and will continue.
    if high_pressure:
        if danger:
            bid = 0.95 * DAILY_SALARY
        else:
            # Slightly above their expected top bid but still budget-safe
            # Use yesterday_highest as anchor; add a small premium.
            premium = 0.08 * DAILY_SALARY
            bid = min(DAILY_SALARY, yesterday_highest + premium)
            # If supply is low, add more premium.
            if supply_units <= 2.0:
                bid = min(DAILY_SALARY, bid + 0.05 * DAILY_SALARY)
        return min(budget, bid)

    # If they bid moderately high, we match partially to avoid losing all water.
    if medium_pressure:
        if danger:
            bid = 0.75 * DAILY_SALARY
        else:
            # Match between target_min and their bid level.
            anchor = yesterday_highest if yesterday_highest is not None else target_min
            bid = 0.55 * anchor + 0.45 * target_min
            # If supply is low, increase.
            if supply_units <= 2.0:
                bid *= 1.15
        return min(budget, bid)

    # Low pressure yesterday: we can undercut slightly unless we're in danger.
    if danger:
        bid = 0.65 * DAILY_SALARY
    else:
        # Conservative: enough to stay in the game, but not to waste budget.
        # Use supply_units to decide: lower supply => bid more.
        if supply_units <= 1.9:
            bid = 0.50 * DAILY_SALARY
        elif supply_units <= 2.6:
            bid = 0.42 * DAILY_SALARY
        else:
            bid = 0.34 * DAILY_SALARY

        # If they had a second-highest bid, we can try to be slightly below it.
        if yesterday_second is not None:
            bid = min(bid, 0.92 * yesterday_second + 0.02 * DAILY_SALARY)

    return min(budget, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # If I'm the last one standing, bid minimal to save budget.
    if num_alive_opponents == 0:
        return min(my_status['budget'], 1.0)

    # 1. Look at yesterday's situation (Trace) for all active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Determine my bid based on my HP, budget, and opponent's last actions.

    # Critical HP: If my HP is very low, bid very high to survive.
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Low HP: If my HP is low, bid high.
    if my_status['hp'] <= 4:
        # If opponents bid high yesterday, I need to match or slightly exceed.
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            return min(my_status['budget'], highest_prev_bid + 5)
        # Otherwise, bid a solid amount to secure water.
        return min(my_status['budget'], DAILY_SALARY * 0.75)

    # Moderate/Healthy HP: More flexible.
    # Consider current supply vs demand.
    current_supply = day_context['supply']
    # If supply is tight (e.g., less than enough for everyone)
    if current_supply < WATER_REQ * (num_alive_opponents + 1):
        # Competition is likely.
        # If yesterday's highest bid was significant, slightly outbid it.
        if highest_prev_bid >= DAILY_SALARY * 0.5:
            return min(my_status['budget'], highest_prev_bid + 2)
        # Otherwise, bid a reasonable amount to secure water.
        return min(my_status['budget'], DAILY_SALARY * 0.6)
    else:
        # Supply is relatively abundant.
        # If yesterday's bids were high, maybe opponents are bluffing or desperate.
        # If I have good HP, I can try to bid a bit lower to save money.
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            return min(my_status['budget'], DAILY_SALARY * 0.5)
        # If bids were generally low or moderate, bid slightly above average or a safe amount.
        return min(my_status['budget'], max(DAILY_SALARY * 0.4, highest_prev_bid + 1))

    # Fallback / Default bid (should be caught by previous conditions)
    return min(my_status['budget'], DAILY_SALARY * 0.5)
